\set ON_ERROR_STOP on
-- Explicit non-production QA load. No provider, webhook, outbox or ledger calls.
-- Password hash is injected by the operator via a private psql variable.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('ieventplux-qa-20261127'));
DO $$ BEGIN
 IF current_user <> 'ieventplux_app' THEN RAISE EXCEPTION 'Run as application role only'; END IF;
 IF EXISTS(SELECT 1 FROM "User" WHERE id LIKE 'qa27-%' OR email LIKE '%@qa.ieventplux.invalid') OR EXISTS(SELECT 1 FROM "Event" WHERE id LIKE 'qa27-%') OR EXISTS(SELECT 1 FROM "MarketplaceStore" WHERE id LIKE 'qa27-%') THEN RAISE EXCEPTION 'QA batch already exists; refuse overwrite'; END IF;
END $$;
-- Reference categories are permanent standard taxonomy, not QA records. Only fill missing slugs.
SELECT 'qa27-'||k,k||'@qa.ieventplux.invalid',:'password_hash','[DEMO] '||n,c,CASE WHEN k='unverified' THEN NULL ELSE now() END,'{"email":false,"sms":false,"push":false,"marketing":false}',now() FROM (VALUES
('organizer','Nana Asare','Accra'),('church','Grace Mensah','Tema'),('tech','Kofi Agyeman','Kumasi'),('festival','Abena Owusu','Cape Coast'),('pending','Esi Boateng','Ho'),('vendor','Kwame Badu','Accra'),('vendor2','Akua Dede','Kumasi'),('buyer','Ama Nyarko','Accra'),('buyer2','Kojo Quaye','Tema'),('buyer3','Efua Lartey','Ho'),('staff','Kweku Adjei','Accra'),('finance','Adwoa Tetteh','Accra'),('unverified','New Applicant','Accra')) AS a(k,n,c);
SELECT 'qa27-event-'||k,'qa27-org-'||o,'[DEMO] '||n,'qa27-'||k,'Fictional event for staging QA — no real booking or venue.','Synthetic event to test discovery, organizers, attendee tickets, programme, audience interaction and administration. All amounts and sales are simulated.',cat,'/images/posters/'||poster||'.png',m,v,s,CASE WHEN m='VIRTUAL' THEN NULL ELSE 'qa27-venue-qa27-org-'||o END,org.city,now()+make_interval(days=>days,hours=>h),now()+make_interval(days=>days,hours=>h+3),CASE WHEN s IN ('PUBLISHED','LIVE','ENDED') THEN now()-interval '60 days' ELSE NULL END,org."ownerId",now(),500 FROM (VALUES
('music','events','Accra Music and Talent Night','concert','gospel-concert','PHYSICAL','PUBLIC','PUBLISHED',7,0),
('business','events','SME Growth and Innovation Forum','conference','business-summit','HYBRID','PUBLIC','PUBLISHED',12,0),
('wedding','events','Bridal and Lifestyle Showcase','wedding','wedding-expo','PHYSICAL','PUBLIC','PUBLISHED',24,0),
('prayer','church','Evening of Hope and Worship','ministry','prayer-night','HYBRID','PUBLIC','PUBLISHED',4,0),
('leaders','church','Community Leadership Summit','conference','church-conference','PHYSICAL','PUBLIC','PUBLISHED',18,0),
('carols','church','Festive Choir Celebration','concert','carols-night','HYBRID','PUBLIC','PUBLISHED',22,0),
('coding','tech','Full Stack Developer Workshop','bootcamp','tech-bootcamp','VIRTUAL','PUBLIC','PUBLISHED',9,0),
('arts','festival','Young Creatives Workshop','workshop','youth-workshop','PHYSICAL','PUBLIC','PUBLISHED',11,0),
('food','festival','Coastal Food and Arts Festival','festival','food-festival','PHYSICAL','PUBLIC','PUBLISHED',30,0),
('walk','festival','Community Wellness Walk','sports-health','health-walk','PHYSICAL','PUBLIC','PUBLISHED',14,0),
('live','events','Audience Engagement Practice Room','community','business-summit','VIRTUAL','PUBLIC','LIVE',0,-1),
('pastmusic','events','Previous Music Awards','concert','gospel-concert','PHYSICAL','PUBLIC','ENDED',-20,0),
('pastforum','events','Previous Business Conference','conference','business-summit','HYBRID','PUBLIC','ENDED',-10,0),
('pastchurch','church','Previous Fellowship Celebration','church-service','carols-night','PHYSICAL','PUBLIC','ENDED',-35,0),
('pasttech','tech','Previous Coding Meetup','workshop','tech-bootcamp','VIRTUAL','PUBLIC','ENDED',-7,0),
('private','events','Private Planning Meeting','community','business-summit','VIRTUAL','INVITE_ONLY','PUBLISHED',3,0),
('draft','events','New Organizer Draft','conference','business-summit','PHYSICAL','PUBLIC','DRAFT',40,0),
('pending','pending','Unpublished Launch Plan','community','youth-workshop','PHYSICAL','PUBLIC','DRAFT',45,0)
) a(k,o,n,cat,poster,m,v,s,days,h) JOIN "Organization" org ON org.id='qa27-org-'||o;
-- Existing historical sales are simulated. Paid tiers' sales windows closed, so no new real paid checkout is possible on the fixtures.
SELECT e.id||'-regular',e.id,e."orgId",'Demo Regular',e.mode,CASE WHEN e.id IN ('qa27-event-walk','qa27-event-arts','qa27-event-live','qa27-event-private','qa27-event-prayer') THEN 0 ELSE 5000 END,100,0,CASE WHEN e.id IN ('qa27-event-walk','qa27-event-arts','qa27-event-live','qa27-event-private','qa27-event-prayer') THEN NULL ELSE now()-interval '1 day' END,0 FROM "Event" e WHERE e.id LIKE 'qa27-event-%';
-- Three distinct buyers across selected upcoming and past events, two tickets per order.
SELECT 'qa27-order-'||e.id||'-'||u.id,'ORD-QA27-'||upper(substr(md5(e.id||u.id),1,12)),e."orgId",e.id,u.id,u."displayName",u.email,CASE WHEN t."priceMinor"=0 THEN 'FREE' ELSE 'PAID' END,'PAID',2*t."priceMinor",0,2*t."priceMinor",least(now()-interval '2 days',e."startsAt"-interval '5 days'),least(now()-interval '2 days',e."startsAt"-interval '5 days'),now(),'{"synthetic":true,"name":"QA only — no settlement"}' FROM "Event" e JOIN "TicketType" t ON t.id=e.id||'-regular' CROSS JOIN "User" u WHERE e.id IN ('qa27-event-music','qa27-event-business','qa27-event-food','qa27-event-walk','qa27-event-prayer','qa27-event-pastmusic','qa27-event-pastforum','qa27-event-pastchurch','qa27-event-pasttech','qa27-event-coding') AND u.id IN ('qa27-buyer','qa27-buyer2','qa27-buyer3');
UPDATE "TicketType" t SET "soldCount"=(SELECT count(*) FROM "Ticket" k WHERE k."ticketTypeId"=t.id) WHERE t.id LIKE 'qa27-event-%';
-- Extra master-architecture scenarios: pending providers, never falsely certified.
COMMIT;
