INSERT INTO "Category" (id,name,slug,icon,"sortOrder") VALUES
('qa27-cat-1','Church Service','church-service','church',1),('qa27-cat-2','Concert','concert','music',2),('qa27-cat-3','Conference','conference','presentation',3),('qa27-cat-4','Workshop','workshop','wrench',4),('qa27-cat-5','Bootcamp','bootcamp','code',5),('qa27-cat-6','Wedding','wedding','heart',6),('qa27-cat-7','Community','community','users',7),('qa27-cat-8','Ministry','ministry','sparkles',8),('qa27-cat-9','Festival','festival','party-popper',9),('qa27-cat-10','Sports & Health','sports-health','activity',10) ON CONFLICT (slug) DO NOTHING;
INSERT INTO "User" (id,email,"passwordHash","displayName",city,"emailVerifiedAt","notifPrefs","updatedAt")
INSERT INTO "Organization" (id,name,slug,"orgType","ownerId",status,city,description,"verifiedAt","updatedAt") SELECT 'qa27-org-'||k,'[DEMO] '||n,'qa27-'||k,t,'qa27-'||u,s,c,'Fictional QA organization. No real business or payment activity.',CASE WHEN s='ACTIVE' THEN now() ELSE NULL END,now() FROM (VALUES
('events','Aurora Events Company','COMPANY','organizer','ACTIVE','Accra'),('church','Harbour of Hope Fellowship','CHURCH','church','ACTIVE','Tema'),('tech','Next Horizon Tech Collective','ASSOCIATION','tech','ACTIVE','Kumasi'),('festival','Coastal Culture Productions','COMPANY','festival','ACTIVE','Cape Coast'),('pending','Emerging Events Studio','COMPANY','pending','PENDING_VERIFICATION','Ho')) a(k,n,t,u,s,c);
INSERT INTO "Membership" (id,"orgId","userId",role,"acceptedAt") SELECT 'qa27-member-'||k,'qa27-org-'||k,'qa27-'||u,'OWNER',now() FROM (VALUES ('events','organizer'),('church','church'),('tech','tech'),('festival','festival'),('pending','pending')) a(k,u);
INSERT INTO "Membership" (id,"orgId","userId",role,"acceptedAt") VALUES ('qa27-member-staff','qa27-org-events','qa27-staff','CHECKIN_STAFF',now()),('qa27-member-finance','qa27-org-events','qa27-finance','FINANCE',now());
INSERT INTO "OrganizerVerification" (id,"orgId",status,notes,"decidedAt") SELECT 'qa27-ver-'||id,id,CASE WHEN status='ACTIVE' THEN 'APPROVED' ELSE 'PENDING' END,'Synthetic QA status only',CASE WHEN status='ACTIVE' THEN now() ELSE NULL END FROM "Organization" WHERE id LIKE 'qa27-org-%';
INSERT INTO "Venue" (id,"orgId",name,city,address,capacity,"accessibilityInfo") SELECT 'qa27-venue-'||id,id,'[DEMO] '||city||' Community Hall',city,'Fictional location for testing only',500,'Step-free demo entrance' FROM "Organization" WHERE id LIKE 'qa27-org-%';
INSERT INTO "Event" (id,"orgId",title,slug,summary,description,"categorySlug","coverImageUrl",mode,visibility,status,"venueId",city,"startsAt","endsAt","publishedAt","createdBy","updatedAt","capacityTotal")
INSERT INTO "TicketType" (id,"eventId","orgId",name,kind,"priceMinor",quota,"soldCount","saleEndsAt","sortOrder")
INSERT INTO "TicketType" (id,"eventId","orgId",name,kind,"priceMinor",quota,"saleEndsAt","sortOrder") SELECT e.id||'-vip',e.id,e."orgId",'Demo VIP',e.mode,15000,40,now()-interval '1 day',1 FROM "Event" e WHERE e.id IN ('qa27-event-music','qa27-event-business','qa27-event-pastmusic','qa27-event-pastforum','qa27-event-food','qa27-event-wedding');
INSERT INTO "Order" (id,reference,"orgId","eventId","userId","buyerName","buyerEmail",kind,status,"subtotalMinor","platformFeeMinor","totalMinor","paidAt","createdAt","updatedAt","feeSnapshot")
INSERT INTO "OrderItem" (id,"orderId","ticketTypeId",qty,"unitPriceMinor","lineTotalMinor") SELECT o.id||'-item',o.id,o."eventId"||'-regular',2,o."totalMinor"/2,o."totalMinor" FROM "Order" o WHERE o.id LIKE 'qa27-order-%';
INSERT INTO "PaymentAttempt" (id,"orderId",provider,reference,status,"amountMinor","verifiedAt","initiatedAt","rawResult") SELECT o.id||'-payment',o.id,'SIMULATOR',o.reference||'-A1','SUCCESS',o."totalMinor",o."paidAt",o."createdAt",'{"synthetic":true,"noProviderCall":true}' FROM "Order" o WHERE o.id LIKE 'qa27-order-%' AND o."totalMinor">0;
INSERT INTO "Ticket" (id,"eventId","ticketTypeId","orderId","userId","holderName","holderEmail",code,"qrSecret",status,"issuedAt","checkedInAt") SELECT o.id||'-ticket-'||n,o."eventId",o."eventId"||'-regular',o.id,o."userId",o."buyerName",o."buyerEmail",'TKT-QA27-'||upper(substr(md5(o.id||n),1,14)),md5(random()::text||o.id||n||clock_timestamp()::text),CASE WHEN e.status='ENDED' AND n=1 THEN 'CHECKED_IN' ELSE 'VALID' END,o."paidAt",CASE WHEN e.status='ENDED' AND n=1 THEN e."startsAt" ELSE NULL END FROM "Order" o JOIN "Event" e ON e.id=o."eventId" CROSS JOIN generate_series(1,2) n WHERE o.id LIKE 'qa27-order-%';
INSERT INTO "Rsvp" (id,"eventId","userId",name,email,status) SELECT 'qa27-rsvp-'||u.id,'qa27-event-private',u.id,u."displayName",u.email,CASE WHEN u.id='qa27-buyer' THEN 'APPROVED' ELSE 'PENDING' END FROM "User" u WHERE u.id IN ('qa27-buyer','qa27-buyer2');
INSERT INTO "EventContributor" (id,"eventId",name,role,topic,"sortOrder","updatedAt") SELECT e.id||'-speaker',e.id,'[DEMO] Jordan Amani','MAIN_SPEAKER','Practical insights and audience engagement',0,now() FROM "Event" e WHERE e.id LIKE 'qa27-event-%';
INSERT INTO "EventContributor" (id,"eventId",name,role,topic,"sortOrder","updatedAt") VALUES ('qa27-artist','qa27-event-music','[DEMO] Horizon Band','HEADLINER','Live music showcase',1,now());
