INSERT INTO "AudienceQuestion" (id,"eventId","userId",body,status,answer,"answeredById","answeredAt") VALUES ('qa27-question-a','qa27-event-live','qa27-buyer2','Will the slides be available after the session?','ANSWERED','Yes, the fictional programme includes a recap.','qa27-organizer',now()),('qa27-question-b','qa27-event-live','qa27-buyer3','Can we ask questions during the presentation?','NEW',NULL,NULL,NULL);
