INSERT INTO "CompetitionVote" (id,"competitionId","categoryId","nomineeId","userId") VALUES ('qa27-ballot-a','qa27-awards','qa27-award-artist','qa27-nominee-a','qa27-buyer2'),('qa27-ballot-b','qa27-awards','qa27-award-band','qa27-nominee-c','qa27-buyer3');
INSERT INTO "MarketplaceStore" (id,slug,"ownerId",name,category,description,city,status,"verificationState","updatedAt") SELECT 'qa27-store-'||k,'qa27-shop-'||k,'qa27-'||u,'[DEMO] '||n,c,'Fictional marketplace vendor; no real sales or payment.',city,'ACTIVE','UNVERIFIED',now() FROM (VALUES ('apparel','vendor','Coastal Event Apparel','Fashion & Clothing','Accra'),('decor','vendor2','Golden Lantern Decor','Events & Decor','Kumasi'),('gifts','vendor','Horizon Souvenir Shop','Gifts & Souvenirs','Accra'),('tech','vendor2','Summit Tech Accessories','Electronics','Kumasi')) a(k,u,n,c,city);
INSERT INTO "MarketplaceProduct" (id,"storeId",slug,name,description,category,"productKind",status,specifications,"updatedAt") SELECT 'qa27-product-'||k,'qa27-store-'||s,'qa27-'||k,'[DEMO] '||n,'Fictional stock item for basket, SKU, inventory and request tests.',category,'GOODS','ACTIVE','{"Material":"Demo sample","Warranty":"Not a real product"}',now() FROM (VALUES ('shirt','apparel','Festival T-shirt','Apparel'),('cap','apparel','Embroidered Cap','Apparel'),('hoodie','apparel','Event Hoodie','Apparel'),('lanyard','apparel','VIP Lanyard','Apparel'),('lantern','decor','Table Lantern','Decor'),('cloth','decor','Table Linen','Decor'),('banner','decor','Backdrop Banner','Decor'),('flowers','decor','Decorative Flowers','Decor'),('mug','gifts','Commemorative Mug','Souvenir'),('bag','gifts','Canvas Tote','Souvenir'),('notebook','gifts','Event Notebook','Souvenir'),('badge','gifts','Keepsake Badge','Souvenir'),('cable','tech','USB-C Cable','Electronics'),('stand','tech','Phone Stand','Electronics'),('light','tech','Portable LED Light','Electronics'),('case','tech','Accessory Pouch','Electronics')) a(k,s,n,category);
INSERT INTO "MarketplaceVariant" (id,"storeId","productId",sku,title,"priceMinor","stockOnHand","optionValues","updatedAt") SELECT p.id||'-'||v,p."storeId",p.id,upper(replace(p.id,'qa27-product-','QA27-'))||'-'||v,CASE WHEN v=1 THEN 'Standard' ELSE 'Premium' END,2500+v*2000+((row_number() OVER (ORDER BY p.id,v))::int*500),CASE WHEN p.id='qa27-product-badge' THEN 0 ELSE 10+v*8 END,json_build_object('Edition',CASE WHEN v=1 THEN 'Standard' ELSE 'Premium' END)::text,now() FROM "MarketplaceProduct" p CROSS JOIN generate_series(1,2) v WHERE p.id LIKE 'qa27-product-%';
INSERT INTO "MarketplaceStockMovement" (id,"variantId","actorId","requestKey",reason,"qtyDelta","balanceAfter") SELECT v.id||'-stock',v.id,s."ownerId",'qa27-initial-'||v.id,'Synthetic opening inventory',v."stockOnHand",v."stockOnHand" FROM "MarketplaceVariant" v JOIN "MarketplaceStore" s ON s.id=v."storeId" WHERE v.id LIKE 'qa27-product-%' AND v."stockOnHand">0;
INSERT INTO "MarketplacePurchaseRequest" (id,"storeId","buyerId","requestKey",fingerprint,currency,"totalMinor","unitCount",items,status) SELECT 'qa27-request-'||v.id,v."storeId",CASE WHEN x.status='ACKNOWLEDGED' THEN 'qa27-buyer2' ELSE 'qa27-buyer' END,'qa27-request-'||v.id,md5(v.id),'GHS',v."priceMinor"*2,2,jsonb_build_array(jsonb_build_object('variantId',v.id,'sku',v.sku,'variantTitle',v.title,'productId',p.id,'productName',p.name,'quantity',2,'unitPriceMinor',v."priceMinor",'lineMinor',v."priceMinor"*2,'currency','GHS')),x.status FROM (VALUES ('qa27-product-shirt-1','REQUESTED'),('qa27-product-mug-1','ACKNOWLEDGED'),('qa27-product-lantern-1','DECLINED'),('qa27-product-cable-1','WITHDRAWN')) x(id,status) JOIN "MarketplaceVariant" v ON v.id=x.id JOIN "MarketplaceProduct" p ON p.id=v."productId";
